/**
 * @name String formatting injection
 * @description User input flowing to string formatting operations can lead to injection attacks
 * @kind path-problem
 * @problem.severity warning
 * @id py/string-format-injection
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module StringFormatConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Built-in format() function
    exists(API::CallNode call |
      call = API::builtin("format").getACall() and
      sink = call.getArg(0)
    )
    or
    // str.format() method
    exists(API::CallNode call |
      call = API::builtin("str.format").getACall() and
      sink = call.getArg(0)
    )
    or
    // string.Template().substitute()
    exists(API::CallNode templateCall, API::CallNode substituteCall |
      templateCall = API::moduleImport("string").getMember("Template").getACall() and
      substituteCall = templateCall.getReturn().getMember("substitute").getACall() and
      sink = substituteCall.getArg(0)
    )
    or
    // string.Template().safe_substitute()
    exists(API::CallNode templateCall, API::CallNode safeSubstituteCall |
      templateCall = API::moduleImport("string").getMember("Template").getACall() and
      safeSubstituteCall = templateCall.getReturn().getMember("safe_substitute").getACall() and
      sink = safeSubstituteCall.getArg(0)
    )
    or
    // jinja2.Template().render()
    exists(API::CallNode templateCall, API::CallNode renderCall |
      templateCall = API::moduleImport("jinja2").getMember("Template").getACall() and
      renderCall = templateCall.getReturn().getMember("render").getACall() and
      sink = renderCall.getArg(0)
    )
    or
    // mako.Template().render()
    exists(API::CallNode templateCall, API::CallNode renderCall |
      templateCall = API::moduleImport("mako").getMember("Template").getACall() and
      renderCall = templateCall.getReturn().getMember("render").getACall() and
      sink = renderCall.getArg(0)
    )
  }
}

module StringFormatFlow = TaintTracking::Global<StringFormatConfig>;
import StringFormatFlow::PathGraph

from StringFormatFlow::PathNode source, StringFormatFlow::PathNode sink
where StringFormatFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "String format injection from $@.", source.getNode(), "user input"

/**
 * @name Information disclosure through logging
 * @description User input flowing to logging functions can lead to information disclosure
 * @kind path-problem
 * @problem.severity warning
 * @id py/information-disclosure
 * @tags security
 *        external/cwe/cwe-532
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module InfoDisclosureConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Logging functions
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("logging").getMember(["debug", "info", "warning", "error", "critical"]).getACall() or
      call = API::builtin("print").getACall()
    |
      // The sink is the message argument (first argument for logging functions)
      sink = call.getArg(0)
    )
  }
}

module InfoDisclosureFlow = TaintTracking::Global<InfoDisclosureConfig>;
import InfoDisclosureFlow::PathGraph

from InfoDisclosureFlow::PathNode source, InfoDisclosureFlow::PathNode sink
where InfoDisclosureFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Information disclosure from $@.", source.getNode(), "user input"
